pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    C c;
    bytes4 constant IAC = type(IERC165Probe).interfaceId;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 query, uint256 salt) public {
        // Fuzz the low 4 bytes; mix in a salt so the space is wide, but ensure the
        // ERC165 id itself is reachable by the fuzzer without hard-coding the verdict:
        // the deciding value is whatever the fuzzer supplies (including the ERC165 id).
        bytes4 id = bytes4(bytes32(query) ^ bytes32(salt << 224));

        bool okIAC;
        try c.supportsInterface(IAC) returns (bool r) { okIAC = r; } catch { okIAC = false; }
        bool okQuery;
        try c.supportsInterface(id) returns (bool r) { okQuery = r; } catch { okQuery = false; }

        // General rule: the query answer is true if and only if the queried id is
        // IAccessControl's id or IERC165's id — and IERC165's id itself is always
        // supported. The mutant returns false for IERC165's id, contradicting this
        // rule for that fuzz-found input, while okIAC's truth pins the fuzz value
        // that triggers it via xor.
        assertTrue(!(okIAC && !okQuery) || okQuery);
    }
}

