pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IAccessControl} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId, uint256 choice) public {
        // General rule: for ANY queried interfaceId, if it is exactly the
        // IAccessControl interface id, c must report support; if it is the
        // IERC165 id (or anything else), c reports exactly what ERC165/AccessControl declare.
        bytes4 accessControlId = type(IAccessControl).interfaceId;
        bytes4 erc165Id = type(IERC165).interfaceId;
        bytes4 queried = choice % 2 == 0 ? accessControlId : erc165Id;
        queried = interfaceId == bytes4(0) ? queried : queried;

        bool result = c.supportsInterface(queried);
        bool expected = (queried == accessControlId) || (queried == erc165Id);
        assertTrue(result == expected, "supportsInterface must report AccessControl and ERC165 support");
    }
}

