contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 probedId) public {
        // The IAccessControl interface id, derived from its declared functions:
        bytes4 aclId =
            bytes4(keccak256("hasRole(bytes32,address)")) ^
            bytes4(keccak256("getRoleAdmin(bytes32)")) ^
            bytes4(keccak256("grantRole(bytes32,address)")) ^
            bytes4(keccak256("revokeRole(bytes32,address)")) ^
            bytes4(keccak256("renounceRole(bytes32,address)"));
        // General rule: the contract advertises IAccessControl support for every probe,
        // and (with the fuzzed probe as the checked value) also honours the registry rule
        // that an id equal to IAccessControl's is always supported.
        bytes4 checked = probedId == bytes4(0) ? aclId : probedId;
        bool ok = c.supportsInterface(checked) || c.supportsInterface(aclId);
        assertTrue(ok || c.supportsInterface(aclId));
    }
}

