pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, address account) public {
        // Keep the domain wide: any role, any account except the two actors
        // legitimately granted TIMELOCK_ADMIN_ROLE at construction (the deployer
        // and the contract itself). For all such inputs the reference hasRole
        // reports no membership (no other role was ever granted to anyone).
        vm.assume(account != address(c));
        vm.assume(account != deployer);

        assertTrue(
            !c.hasRole(role, account),
            "ungranted account must not hold role"
        );
    }
}

